import { useEffect, useState } from 'react';
import { useSelector } from 'react-redux';
import { getTransactionDetails, updateTransaction } from '../services/api';
import { useParams, useNavigate } from 'react-router-dom';

function TransactionDetails() {
    const { transactionId } = useParams();
    const [transaction, setTransaction] = useState(null);
    const [isEditing, setIsEditing] = useState(false);
    const [formData, setFormData] = useState({});
    const { token } = useSelector(state => state.auth);
    const navigate = useNavigate();

    useEffect(() => {
        const fetchTransaction = async () => {
            try {
                const data = await getTransactionDetails(transactionId, token);
                setTransaction(data);
                setFormData({
                    description: data.description,
                    category: data.category,
                    notes: data.notes
                });
            } catch (error) {
                console.error('Failed to fetch transaction', error);
            }
        };
        fetchTransaction();
    }, [transactionId, token]);

    const handleSubmit = async (e) => {
        e.preventDefault();
        try {
            await updateTransaction(transactionId, formData, token);
            setIsEditing(false);
            // Refresh data
            const updated = await getTransactionDetails(transactionId, token);
            setTransaction(updated);
        } catch (error) {
            console.error('Failed to update transaction', error);
        }
    };

    if (!transaction) return <div>Loading...</div>;

    return (
        <div className="transaction-details">
            <button onClick={() => navigate(-1)}>Back</button>

            {isEditing ? (
                <form onSubmit={handleSubmit}>
                    <div>
                        <label>Description:</label>
                        <input
                            value={formData.description}
                            onChange={(e) => setFormData({...formData, description: e.target.value})}
                        />
                    </div>
                    <div>
                        <label>Category:</label>
                        <input
                            value={formData.category}
                            onChange={(e) => setFormData({...formData, category: e.target.value})}
                        />
                    </div>
                    <div>
                        <label>Notes:</label>
                        <textarea
                            value={formData.notes}
                            onChange={(e) => setFormData({...formData, notes: e.target.value})}
                        />
                    </div>
                    <button type="submit">Save</button>
                    <button type="button" onClick={() => setIsEditing(false)}>Cancel</button>
                </form>
            ) : (
                <>
                    <h2>Transaction Details</h2>
                    <p>Date: {new Date(transaction.date).toLocaleString()}</p>
                    <p>Description: {transaction.description}</p>
                    <p>Amount: ${transaction.amount.toFixed(2)}</p>
                    <p>Balance: ${transaction.balance.toFixed(2)}</p>
                    <p>Category: {transaction.category}</p>
                    <p>Notes: {transaction.notes}</p>
                    <button onClick={() => setIsEditing(true)}>Edit</button>
                </>
            )}
        </div>
    );
}

export default TransactionDetails;
